CREATE TABLE IF NOT EXISTS ke_users(id BIGSERIAL PRIMARY KEY,full_name TEXT NOT NULL DEFAULT 'Học viên',email TEXT UNIQUE,phone TEXT UNIQUE,birth_date DATE,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'student',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ke_products(id BIGSERIAL PRIMARY KEY,type TEXT NOT NULL CHECK(type IN ('course','book','reading')),title TEXT NOT NULL,slug TEXT UNIQUE NOT NULL,cover_url TEXT,short_desc TEXT,description TEXT,is_free BOOLEAN NOT NULL DEFAULT false,is_published BOOLEAN NOT NULL DEFAULT true,position INT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ke_chapters(id BIGSERIAL PRIMARY KEY,product_id BIGINT NOT NULL REFERENCES ke_products(id) ON DELETE CASCADE,title TEXT NOT NULL,position INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS ke_lessons(id BIGSERIAL PRIMARY KEY,chapter_id BIGINT NOT NULL REFERENCES ke_chapters(id) ON DELETE CASCADE,title TEXT NOT NULL,description TEXT,position INT NOT NULL DEFAULT 0,is_free BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS ke_resources(id BIGSERIAL PRIMARY KEY,lesson_id BIGINT NOT NULL REFERENCES ke_lessons(id) ON DELETE CASCADE,kind TEXT NOT NULL,title TEXT NOT NULL,url TEXT NOT NULL,duration_seconds INT,position INT NOT NULL DEFAULT 0,is_free BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS ke_quizzes(id BIGSERIAL PRIMARY KEY,lesson_id BIGINT NOT NULL REFERENCES ke_lessons(id) ON DELETE CASCADE,title TEXT NOT NULL,pass_score NUMERIC(6,2) NOT NULL DEFAULT 5);
CREATE TABLE IF NOT EXISTS ke_entitlements(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES ke_users(id) ON DELETE CASCADE,product_id BIGINT NOT NULL REFERENCES ke_products(id) ON DELETE CASCADE,activation_code TEXT UNIQUE NOT NULL,expires_at TIMESTAMPTZ,UNIQUE(user_id,product_id));
CREATE TABLE IF NOT EXISTS ke_progress(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES ke_users(id) ON DELETE CASCADE,lesson_id BIGINT NOT NULL REFERENCES ke_lessons(id) ON DELETE CASCADE,completed BOOLEAN NOT NULL DEFAULT false,updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(user_id,lesson_id));
CREATE TABLE IF NOT EXISTS ke_menu(id BIGSERIAL PRIMARY KEY,label TEXT NOT NULL,url TEXT NOT NULL,position INT NOT NULL DEFAULT 0,is_active BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS "session"("sid" varchar NOT NULL PRIMARY KEY,"sess" json NOT NULL,"expire" timestamp(6) NOT NULL);
CREATE INDEX IF NOT EXISTS idx_session_expire ON "session"("expire");
